{
  "book_code": "2MCE",
  "chapter": 17,
  "verses": [
    {
      "chapter": 17,
      "verse": 1,
      "text_ar": "حبّة القمح لا تنمو ولا تُثمر إلا إذا سُحقت أولاً (دُمرت). ولكن إذا سُحقت حبّة القمح، فإنها تُرسل جذورها إلى الأرض، وتُخرج أوراقها، وتُنتج براعم، وتُثمر.",
      "review_notes_ar": []
    },
    {
      "chapter": 17,
      "verse": 2,
      "text_ar": "أنت تعلم أن حبة قمح واحدة تصبح عدة حبات.",
      "review_notes_ar": []
    },
    {
      "chapter": 17,
      "verse": 3,
      "text_ar": "كذلك، تنمو هذه الحبة من خلال ارتفاعها من الماء والرياح وندى الأرض. لا يمكن للقمح أن يُثمر دون الشمس، وتعمل الشمس محلًّا للنار.",
      "review_notes_ar": []
    },
    {
      "chapter": 17,
      "verse": 4,
      "text_ar": "تعمل الرياح محلًّا للروح؛ فالقُمح لا يثمر بلا ريح، والماء يروي الأرض لتُشبعها.",
      "review_notes_ar": []
    },
    {
      "chapter": 17,
      "verse": 5,
      "text_ar": "بعد أن تشرب الأرض، التي هي رماد، الماء، تُنتج جذورها، وتعلو أطرافها. تُثمر وفقًا لما باركها الرب.",
      "review_notes_ar": []
    },
    {
      "chapter": 17,
      "verse": 6,
      "text_ar": "حبّة القمح مثال على آدم، فيه تسكن روحٌ حية خلقها الرب. وكذلك، يَشرب كرمة العنب الماء وتُرسل جذورها.",
      "review_notes_ar": []
    },
    {
      "chapter": 17,
      "verse": 7,
      "text_ar": "ندى الغفران من الرب يروي أطراف الكروم الطويلة، يرسل الماء صعودًا إلى الأوراق. تُبرعم من حرارة الشمس، وبإرادة الرب تُثمر.",
      "review_notes_ar": []
    },
    {
      "chapter": 17,
      "verse": 8,
      "text_ar": "تُنتج عبقًا طيبًا يُبهج العقل. عندما يُؤكل، يُشبع كالْماء الذي يطفئ العطش أو كالحبوب التي تُشبع الجوع. عندما يُعصر، يصبح دمّ العنقود.",
      "review_notes_ar": []
    },
    {
      "chapter": 17,
      "verse": 9,
      "text_ar": "كما قيل في المزامير: «النبيذ يُبهج قلب الإنسان». عندما يشربونه، يُبهج القلب. عندما يفتح الإنسان فمه ويشرب، يمتلئ، وتدفق الدم إلى قلبه.",
      "review_notes_ar": []
    },
    {
      "chapter": 17,
      "verse": 10,
      "text_ar": "لأن سُكْر العنب قد يضلّ الإنسان ويحرم عقله، فيجعل الحفر والجبال تبدو كالمروج الواسعة؛ ولا يلحظ العقبات أو الأشواك تحت قدميه ويديه.",
      "review_notes_ar": []
    },
    {
      "chapter": 17,
      "verse": 11,
      "text_ar": "فعل الرب ذلك بالثمرة والكرم حتى يُمجد اسمه الذين يؤمنون بأن الموتى سيقيمون والذين يطيعون إرادته.",
      "review_notes_ar": []
    },
    {
      "chapter": 17,
      "verse": 12,
      "text_ar": "في ملكوت السماء، سيُبهج الذين يؤمنون بالقيامة.",
      "review_notes_ar": []
    }
  ]
}
